tool_calls:
{
  echo "name,department_name,salary"
  awk -F, 'NR==FNR {dept[$1]=$2; next} FNR>1 {print $1 "," dept[$2] "," $3}' /data/departments.csv /data/employees.csv
} > /data/report.csv
cat /data/report.csv

